import { LayaModelError } from '../errors/index.js';
import type { ChoiceAnswer, LayaAnswer, NoulAnswer, ScoreAnswer, LayaRouting, LayaUsage } from '../wire.js';
import type { ChoiceSpec, DecisionSpec, LabelSpec, LabelsOf, NoulSpec, ScoreSpec } from './spec.js';

/**
 * Per-call metadata.
 *
 * Provenance is explicit: `model`, `routing` and `usage` are the server's own
 * fields, forwarded unchanged. Everything else is measured or generated by
 * laya-studio.
 */
export interface ResultMeta {
  /** Generated by laya-studio. Not sent to, or returned by, the server. */
  requestId: string;
  /** Measured by laya-studio: full round trip, including network and SDK time. */
  latencyMs: number;
  /**
   * The server's `model` field, verbatim.
   *
   * This is a **model family id** — Laya reports the constant `"laya-rl-agent"`
   * — and NOT the checkpoint that answered. For the checkpoint, read
   * {@link ResultMeta.checkpoint}.
   */
  model: string;
  /**
   * Which checkpoint the server's own Router chose (`english`, `multilingual`,
   * `typed-decisions`) and why. The server's `routing` object, verbatim.
   * Absent if the endpoint did not send one.
   */
  routing?: LayaRouting;
  /**
   * Convenience read of `routing.model` — the checkpoint that actually
   * answered. Derived by laya-studio from the server's `routing` field.
   */
  checkpoint?: string;
  /** The server's token accounting, verbatim. */
  usage?: LayaUsage;
  /** laya-studio's cache, not the server's. Laya does not cache. */
  cached: boolean;
  /** Set by laya-studio when a low-confidence result was replaced by the caller's fallback. */
  fallbackUsed?: boolean;
}

export interface ConfidenceMethods {
  /**
   * Is the answer confident enough to act on?
   *
   * Compares {@link ChoiceResult.confidence} — that is, Laya's
   * `answer_confidence` — against `threshold`, defaulting to the client's
   * configured value (0.8 unless changed).
   *
   * Never compare this threshold against Laya's `confidence` field: that is a
   * different quantity on a different scale. See the note on `confidence`.
   */
  isConfident(threshold?: number): boolean;
}

export interface ChoiceResult<L extends string = string> extends ConfidenceMethods {
  /** Laya's `choice` field: the option it selected. Verbatim. */
  label: L;
  /**
   * Laya's **`answer_confidence`** field, verbatim — which Laya computes as
   * `max(probabilities)`, the probability mass on the answer it reported.
   *
   * This is the calibrated quantity: it is what Laya's temperature scaling is
   * fitted on and what its published ECE measures, so of the answers returned
   * at confidence c, about c of them are right.
   *
   * It is deliberately NOT Laya's `confidence` field, which is a normalized
   * Shannon entropy over the whole distribution — a different quantity on a
   * different scale, which Laya's own source warns must not be compared
   * against the same threshold. Both are available verbatim on {@link raw}.
   */
  confidence: number;
  /** Laya's `probabilities` map, verbatim. Sums to 1 across the labels you supplied. */
  probabilities: Record<L, number>;
  /** The server's answer object, untouched — including its own `confidence` field. */
  raw: ChoiceAnswer;
  meta: ResultMeta;
}

export interface ScoreResult extends ConfidenceMethods {
  /**
   * Laya's `score` field, verbatim: the **expected value** over the rubric
   * levels, so fractional scores are normal and expected.
   */
  score: number;
  /**
   * Index of the most probable level. **Computed by laya-studio** as the argmax
   * of `probabilities` — Laya does not return it.
   *
   * Note this is the single most likely level, which is not necessarily the
   * level nearest `score`: an expected value of 1.5 can sit between two levels.
   */
  level: number;
  /** The description of {@link level}, read from Laya's `legend`. */
  label: string;
  /**
   * Laya's `answer_confidence` field, verbatim = `max(probabilities)`.
   *
   * This is the probability of the single most likely **level**. It says
   * nothing directly about how precise the expected-value `score` is.
   */
  confidence: number;
  /** Laya's `probabilities` map, verbatim, keyed by level index as a string. */
  probabilities: Record<string, number>;
  /** The server's answer object, untouched — including `legend` and its own `confidence`. */
  raw: ScoreAnswer;
  meta: ResultMeta;
}

export interface NoulResult extends ConfidenceMethods {
  /**
   * **Computed by laya-studio** as `probability > 0.5`. Laya returns only a
   * probability and takes no position on where the cutoff belongs; 0.5 is this
   * SDK's choice. Use {@link probability} directly if you need another cutoff.
   */
  value: boolean;
  /** Laya's `noul` field, verbatim: P(yes), in [0, 1]. */
  probability: number;
  /**
   * Laya's `answer_confidence` field, verbatim.
   *
   * For a noul question this equals Laya's `confidence` field, because over two
   * options `max(p)` and `max(p_yes, 1 - p_yes)` are the same number. The two
   * diverge only for choice and score.
   */
  confidence: number;
  /** The server's answer object, untouched. */
  raw: NoulAnswer;
  meta: ResultMeta;
}

export type AnyResult = ChoiceResult<string> | ScoreResult | NoulResult;

/** Map a decision spec to the result it produces. Order matters: tagged kinds first. */
export type ResultFor<S> = S extends ScoreSpec
  ? ScoreResult
  : S extends NoulSpec
    ? NoulResult
    : S extends ChoiceSpec<infer L>
      ? ChoiceResult<L>
      : S extends LabelSpec
        ? ChoiceResult<LabelsOf<S>>
        : never;

export type DecideResults<D extends Record<string, DecisionSpec>> = {
  [K in keyof D]: ResultFor<D[K]>;
};

/**
 * Attach `isConfident` without making it enumerable.
 *
 * Results are routinely logged and serialized; a method on the object would
 * either be dropped silently by JSON.stringify or show up as noise. Keeping it
 * non-enumerable makes `JSON.stringify(result)` produce exactly the data.
 */
function withConfidence<T extends object>(result: T, confidence: number, defaultThreshold: number): T & ConfidenceMethods {
  Object.defineProperty(result, 'isConfident', {
    value: (threshold: number = defaultThreshold): boolean => confidence >= threshold,
    enumerable: false,
    writable: false,
  });
  return result as T & ConfidenceMethods;
}

function requireAnswer(answers: Record<string, LayaAnswer>, name: string): LayaAnswer {
  const answer = answers[name];
  if (!answer) {
    const available = Object.keys(answers);
    throw new LayaModelError(
      `Laya returned no answer for "${name}".\n\n` +
        (available.length
          ? `The response contained: ${available.join(', ')}.`
          : `The response contained no answers at all.`),
    );
  }
  return answer;
}

function expectType<T extends LayaAnswer['type']>(
  answer: LayaAnswer,
  name: string,
  type: T,
): Extract<LayaAnswer, { type: T }> {
  if (answer.type !== type) {
    throw new LayaModelError(
      `Laya answered "${name}" as a ${answer.type} question, but a ${type} answer was expected.`,
    );
  }
  return answer as Extract<LayaAnswer, { type: T }>;
}

export function toChoiceResult<L extends string>(
  answers: Record<string, LayaAnswer>,
  name: string,
  meta: ResultMeta,
  defaultThreshold: number,
): ChoiceResult<L> {
  const answer = expectType(requireAnswer(answers, name), name, 'choice');
  return withConfidence(
    {
      label: answer.choice as L,
      confidence: answer.answer_confidence,
      probabilities: answer.probabilities as Record<L, number>,
      raw: answer,
      meta,
    },
    answer.answer_confidence,
    defaultThreshold,
  );
}

export function toScoreResult(
  answers: Record<string, LayaAnswer>,
  name: string,
  meta: ResultMeta,
  defaultThreshold: number,
): ScoreResult {
  const answer = expectType(requireAnswer(answers, name), name, 'score');
  let level = 0;
  let best = -1;
  for (const [key, probability] of Object.entries(answer.probabilities)) {
    if (probability > best) {
      best = probability;
      level = Number(key);
    }
  }
  return withConfidence(
    {
      score: answer.score,
      level,
      label: answer.legend[String(level)] ?? String(level),
      confidence: answer.answer_confidence,
      probabilities: answer.probabilities,
      raw: answer,
      meta,
    },
    answer.answer_confidence,
    defaultThreshold,
  );
}

export function toNoulResult(
  answers: Record<string, LayaAnswer>,
  name: string,
  meta: ResultMeta,
  defaultThreshold: number,
): NoulResult {
  const answer = expectType(requireAnswer(answers, name), name, 'noul');
  return withConfidence(
    {
      value: answer.noul > 0.5,
      probability: answer.noul,
      confidence: answer.answer_confidence,
      raw: answer,
      meta,
    },
    answer.answer_confidence,
    defaultThreshold,
  );
}

/** Dispatch on the spec's kind to build the matching result. */
export function toResult(
  answers: Record<string, LayaAnswer>,
  name: string,
  kind: 'choice' | 'score' | 'noul',
  meta: ResultMeta,
  defaultThreshold: number,
): AnyResult {
  if (kind === 'score') return toScoreResult(answers, name, meta, defaultThreshold);
  if (kind === 'noul') return toNoulResult(answers, name, meta, defaultThreshold);
  return toChoiceResult(answers, name, meta, defaultThreshold);
}
